var ALL = [dashboard, analytics, circulation, books, announcementsTab, students, staff, reports, gameTab, settingsTab, teamTab, audit];
var allowed = (t) => t.adminOnly ? isAdmin() : t.need ? t.need === "game" ? hasPerm("game_edit") || hasPerm("game_host") : hasPerm(t.need) : true;
boot(async ({ params }) => {
  const tabs = ALL.filter(allowed);
  const main = qs("#panelMain");
  const open = async (id, query = "") => {
    const tab = tabs.find((t) => t.id === id) ?? tabs[0];
    history.replaceState(null, "", `?tab=${tab.id}`);
    markPanelTab(tab.id);
    const fresh = document.createElement("div");
    main.replaceChildren(fresh);
    try {
      await tab.render(fresh, query);
    } catch (error) {
      mount(fresh, html`<div class="alert alert--danger px px--danger">${friendly(error)}</div>`);
    }
    reveal(fresh);
  };
  document.querySelectorAll(".nav-link[data-tab]").forEach((link) => link.addEventListener("click", (event) => {
    event.preventDefault();
    void open(link.dataset.tab ?? "");
  }));
  await open(params.get("tab") ?? tabs[0].id, params.get("q") ?? "");
});
